TransitView = class("TransitView", ViewBase)
---@class TransitView
function TransitView:initialize()
    ViewBase.initialize(self)
    ViewBase.RegisteAction(self, "TransitViewAction")
end

function TransitView:Awake()
    CommonHelper:HButtonSetCallback("BtnBack", self.gameObject, function(hbtn)
        UIManager:Get():CloseView()
    end)
    CommonHelper:HButtonSetCallback("BtnClubFriend", self.gameObject, function(param)
        CommonHelper:SetUnlockFunc({ GameFunction.Friend }, function()
            FriendSubsystem:Get():SendMsg_GetAllFriends()
            FriendDataManager:Get():SetFriendType(FriendType.Init)
        end)
    end)
    CommonHelper:HButtonSetCallback("BtnClub", self.gameObject, function(param)
        CommonHelper:SetUnlockFunc({ GameFunction.Club }, function()
            local guildId = PlayerDataManager:Get():GetGuildId()
            if guildId == 0 then
                UIManager:Get():OpenView("ClubNoView", CanvasType.MainCanvas, "ClubNoView")
            else
                ClubSubsystem:Get():SendMsg_GuildInfo(ClubInfoType.Self, guildId)
            end
        end)
    end)
    CommonHelper:HButtonSetCallback("BtnAct", self.gameObject, function(param)
        FunctionSkipManager:Get():SkipToFunction(GameFunction.CommonAct)
    end)
    CommonHelper:HButtonSetCallback("BtnShop", self.gameObject, function(param)
        FunctionSkipManager:Get():SkipToFunction(GameFunction.Shop)
    end)
    CommonHelper:HButtonSetCallback("BtnGacha", self.gameObject, function(param)
        CommonHelper:SetUnlockFunc({ GameFunction.Recruit }, function()
            if not RaceRankManager:Get():IsMatching() then
                RecruitSubsystem:Get():SendMsg_RecruitInfo()
            end
        end)
    end)
    CommonHelper:HButtonSetCallback("BtnGiftBag", self.gameObject, function(param)
        FunctionSkipManager:Get():SkipToFunction(GameFunction.PurchasePanel)
    end)
    CommonHelper:HButtonSetCallback("BtnLaboratory", self.gameObject, function(param)
        FunctionSkipManager:Get():SkipToFunction(GameFunction.LabIron)
    end)
    CommonHelper:HButtonSetCallback("BtnGarage", self.gameObject, function(param)
        CommonHelper:SetUnlockFunc({ GameFunction.Garbage }, function()
            if not RaceRankManager:Get():IsMatching() then

                UIManager:Get():OpenView("GarageView", CanvasType.MainCanvas, "GarageView")
                CommonHelper:PlayScreenEffectUIMask()
            end
        end)
    end)

    CommonHelper:HButtonSetCallback("BtnRace", self.gameObject, function(param)
        UIManager:Get():OpenView("RaceView", CanvasType.MainCanvas, "RaceView")
    end)
    CommonHelper:HButtonSetCallback("BtnCustomRace", self.gameObject, function(param)
        UIManager:Get():OpenView("CustomTrackListView", CanvasType.MainCanvas, "CustomTrackListView")
    end)

end

---@param interactivityType InteractivityType
function TransitView:UpdateData(interactivityType)
    CommonHelper:SetGameObjectActive("Club",self.gameObject,interactivityType== InteractivityType.Club)
    CommonHelper:SetGameObjectActive("Shop",self.gameObject,interactivityType== InteractivityType.Shop)
    CommonHelper:SetGameObjectActive("Laboratory",self.gameObject,interactivityType== InteractivityType.LabIron)
    CommonHelper:SetGameObjectActive("Race",self.gameObject,interactivityType== InteractivityType.Race)
end